SCALE=227.18/1024
# Cubics describing ordinary pen strokes; stems may be retraced to join shoulders.
def bez(points,n=100):
 p=np.array(points,float);t=np.linspace(0,1,n)[:,None]
 return (1-t)**3*p[0]+3*(1-t)**2*t*p[1]+3*(1-t)*t*t*p[2]+t**3*p[3]
def line(a,b,n=100):return np.linspace(a,b,n)
def join(*p):return np.concatenate(p)
def stem(base=306):
 return bez([[base,464],[base,486],[base-5,530],[base-8,557]])
def shoulder(base=306):
 return join(bez([[base-8,557],[base-6,530],[base-4,497],[base+1,483]]),bez([[base+1,483],[base+4,472],[base+14,468],[base+20,467]]),bez([[base+20,467],[base+40,467],[base+34,493],[base+33,504]]),bez([[base+33,504],[base+32,520],[base+29,544],[base+27,557]]))
def tail(base=306):
