def n(base):return join(line([base-10,474],[base,464]),stem(base),shoulder(base)[:-100],tail(base))
def i(base):return join(line([base-10,474],[base,464]),bez([[base,464],[base,484],[base-5,526],[base-6,544]]),bez([[base-6,544],[base-7,555],[base-2,559],[base+4,555]]),line([base+4,555],[base+13,549],30))
