def render(paths,angle=35,width=4,thin=.15,ss=3):
 # Nib edge sweeps, not area fills: use quadrilaterals between successive nib poses.
 im=Image.new('L',(1024*ss,1024*ss));d=ImageDraw.Draw(im)
 e=np.array([np.cos(np.deg2rad(angle)),-np.sin(np.deg2rad(angle))])*width/SCALE/2
